def T(n):
    """Applies the transformation T(n) = floor(n/10) + 3*(n mod 10)"""
    if n < 0:
        raise ValueError("Input must be non-negative")
    removed_digit = n % 10
    remaining_number = n // 10
    return remaining_number + 3 * removed_digit

def analyze_sequence(start_n, max_length=1000):
    sequence = [start_n]
    seen = {start_n: 0}
    current = start_n

    for i in range(1, max_length + 1):
        next_val = T(current)

        if next_val in seen:
            # Cycle detected
            start_index = seen[next_val]
            cycle_length = i - start_index
            return sequence, True, start_index, cycle_length

        sequence.append(next_val)
        seen[next_val] = i
        current = next_val

    # No cycle detected within max_length (shouldn't happen for this type of function given the nature of reduction, but good practice)
    return sequence, False, None, None

all_results = {}
# Testing from n=1 to n=1000
for n in range(1, 1001):
    sequence, in_cycle, start_index, cycle_length = analyze_sequence(n)

    if in_cycle:
        # Extract the cycle portion
        cycle_start = sequence[start_index]
        cycle_end = sequence[start_index + cycle_length]

        cycle = sequence[start_index : start_index + cycle_length]

        # Store the structure: (starting number, sequence until cycle, cycle itself)
        all_results[n] = {
            'pre_period': sequence[:start_index],
            'cycle': cycle
        }
    else:
        # If it didn't cycle within 1000 steps, just store the last value
        all_results[n] = {'sequence': sequence[-1]}

# Filter and format the results for output
cycles_found = []
for n, result in all_results.items():
    if 'cycle' in result:
        cycles_found.append((n, result['cycle']))

# Print a summary of the most interesting findings
print("--- Summary of Cycles/Stabilization (N=1 to 1000) ---")

# Print cycles clearly
for n, cycle in cycles_found:
    if len(cycle) == 1:
        print(f"N={n} stabilizes at: {cycle[0]}")
    else:
        print(f"N={n} enters cycle: {cycle}")

# Check for common cycles or stable points
# Stable points are cycles of length 1
stable_points = [c[1][0] for c in cycles_found if len(c[1]) == 1]
print(f"\nIdentified stable points (length 1 cycles): {sorted(list(set(stable_points)))}")

# Check for short cycles
short_cycles = set()
for n, cycle in cycles_found:
    if len(cycle) > 1:
        cycle_tuple = tuple(cycle)
        short_cycles.add(cycle_tuple)

print(f"Identified short cycles (length > 1): {list(short_cycles)}")

